const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startYear = 2012;
  const endYear = 2024;
  const targetYear = 2016;

  // Define the geometry for Punjab and Haryana, India.
  const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const punjab = adminBoundaries.filter(ee.Filter.inList('ADM1_NAME', ['Punjab', 'Haryana']));
  const geometry = punjab.union();

  // 2. Data Acquisition
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14DL')
    .filterDate(`${startYear}-01-01`, `${endYear}-12-31`)
    .select('MaxFRP'); // Selecting a band is good practice

  // 3. Processing & Calculation
  const years = ee.List.sequence(startYear, endYear);
  const yearlyFireCounts = ee.Dictionary.fromLists(
    years.map(y => ee.String(ee.Number(y).int())),
    years.map(year => {
      const startDate = ee.Date.fromYMD(year, 1, 1);
      const endDate = ee.Date.fromYMD(year, 12, 31);
      const filtered = fireCollection.filterDate(startDate, endDate).filterBounds(geometry);
      return filtered.size();
    })
  );

  const fireCountsInfo = yearlyFireCounts.getInfo();

  if (!fireCountsInfo) {
    console.log("Failed to retrieve fire count data.");
    console.log("C3");
    return;
  }

  // 4. Validation & Final Answer
  let maxFires = -1;
  let maxYear = -1;
  let targetYearFires = 0;

  for (const year in fireCountsInfo) {
    const count = fireCountsInfo[year];
    console.log(`Year ${year}: ${count} fire detections`);
    if (count > maxFires) {
      maxFires = count;
      maxYear = parseInt(year);
    }
    if (parseInt(year) === targetYear) {
      targetYearFires = count;
    }
  }

  console.log(`\nYear with most fires: ${maxYear} (${maxFires} detections)`);
  console.log(`Target year (2016) fires: ${targetYearFires}`);

  if (maxYear === -1) {
      console.log("Calculation resulted in no valid maximum year.");
      console.log("C3");
  } else if (maxYear === targetYear) {
    console.log("A");
  } else {
    console.log("B");
  }
}

